#[derive(Clone, Copy, PartialEq, Eq)]
pub enum ActiveAbility {
    None,
    Dash,
    Bow,
    Grenade,
    Tack,
    Mjolnir,
    PokeBall,
    Smoke,
    Rock,
    Roll,
    Meteor,
    Push,
    Freeze,
    Blink,
    GrowthRay,
    ShrinkRay,
    Missile,
    Mine,
    Spike,
    Engine,
    Tesla,
    TimeStop,
    Gust,
    Revival,
    BlackHole,
    Throw,
    Drill,
    Beam,
    Duplicator,
    Magnet,
    Platform,
}

#[derive(Clone, Copy)]
struct DuplicatorRayHit {
    entity: usize,
    distance: Fix,
    position: Vec2,
}

fn active_throw_ability(active: ActiveAbility) -> u32 {
    match active {
        ActiveAbility::Tack => ABILITY_TACK,
        ActiveAbility::Mjolnir => ABILITY_MJOLNIR,
        ActiveAbility::PokeBall => ABILITY_POKE_BALL,
        ActiveAbility::Smoke => ABILITY_SMOKE,
        _ => ABILITY_GRENADE,
    }
}

fn scale_ray_data(data: &data::RolloutData, ability: u32) -> &data::ScaleRayData {
    match ability {
        ABILITY_GROWTH_RAY => &data.scale_rays.growth,
        ABILITY_SHRINK_RAY => &data.scale_rays.shrink,
        _ => unreachable!("not a scale ray"),
    }
}

