                        slot.timers[s] = Fix::ZERO;
                        slot.active = ActiveAbility::Freeze;
                        slot.active_slot = s;
                        slot.ability_entry_action = action;
                        slot.telemetry.ability_activations[s] += 1;
                        slot.gun = GunState {
                            aim,
                            ..GunState::default()
                        };
